import torch,json
cls=json.load(open('/work/cls.json')); toks=json.load(open('/work/toks.json'))
E=W('model.embed_tokens.weight')
import random; random.seed(0)
rnd=random.sample(range(1000,60000),3000)
# add roman tokens class
cls['roman']=[i for i,t in enumerate(toks) if t.strip() in ['I','II','III','IV','V','VI','VII','VIII','IX','X','XI','XII','XX','XL','L','LX','XC','C','CD','D','CM','M','MM','MMM','XV','XXX','CC','CCC']]
cls['weekday']=[i for i,t in enumerate(toks) if t.strip() in ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']]
print(len(cls['roman']),len(cls['weekday']))
out={}
for L in [0,1]:
    n=W(f'model.layers.{L}.ffn_norm.weight')
    w1=W(f'model.layers.{L}.feed_forward.w1.weight'); w3=W(f'model.layers.{L}.feed_forward.w3.weight')
    def act(ids):
        x=E[ids]; x=x/ x.pow(2).mean(1,keepdim=True).sqrt()*n
        return (torch.nn.functional.silu(x@w1.T)*(x@w3.T))
    ar=act(rnd); mr=ar.abs().mean(0); sr=ar.std(0)+1e-6
    out[L]={}
    for k in ['month','weekday','digit','cjk','roman','french','code','mathsym','german','spanish','cyr','japanese','korean','arabic']:
        a=act(cls[k]).abs().mean(0)
        z=(a-mr)/sr
        top=torch.topk(z,128)
        out[L][k]=top.indices.tolist()
        print(L,k,[round(float(v),1) for v in top.values[[0,15,63,127]]])
json.dump(out,open('/work/mlpsel.json','w'))
for L in [0,1]:
    for k in out[L]:
        json.dump({"kind":"mlp_cluster","layer":L,"indices":out[L][k][:64]},open(f'/work/m{L}_{k}_64.json','w'))
        json.dump({"kind":"mlp_cluster","layer":L,"indices":out[L][k][:128]},open(f'/work/m{L}_{k}_128.json','w'))
